// ?friend_applyDifficultyBonusesForObject@Player@@QAEXPAVObject@@_N@Z
// partial score=0.97 date=2026-09-14
// BFME's difficulty bonus grants one upgrade selected by the game mode and
// difficulty. The matched Object caller reaches this Player method through
// retail ILT 0x0002278C.

typedef bool Bool;

enum GameDifficulty
{
	DIFFICULTY_EASY = 0,
	DIFFICULTY_NORMAL,
	DIFFICULTY_HARD
};

enum NameKeyType
{
	NAMEKEY_INVALID = 0
};

class AsciiString
{
public:
	AsciiString() : m_data(0) {}
	~AsciiString();
	void set(const char *text);
	const char *str() const { return m_data ? m_data + 8 : ""; }

private:
	const char *m_data;
};

class PlayerTemplate
{
public:
	char m_padding_00[0xBD];
	Bool m_receivesDifficultyBonus;
};

class AIPlayer
{
public:
	GameDifficulty getAIDifficulty() const;
};

class Player
{
public:
	void friend_applyDifficultyBonusesForObject(class Object *obj, Bool apply);

	void *m_vtable;
	const PlayerTemplate *m_playerTemplate;
	char m_padding_08[0x220 - 0x08];
	AIPlayer *m_ai;
};

class UpgradeTemplate;

class Object
{
public:
	Bool bfmeIsComputerControlled() const;
	Player *getControllingPlayer() const;
	void giveUpgrade(const UpgradeTemplate *upgrade);
};

class GameLogicPortraitShim
{
public:
	Bool isInMultiplayerOrSkirmishGame();
};

class GameLogic
{
public:
	char m_padding_00[0x9C];
	GameDifficulty m_gameDifficulty;
};

class UpgradeCenter
{
public:
	const UpgradeTemplate *findUpgradeByKey(NameKeyType key) const;
};

extern GameLogic *TheBfmeGameLogic;
extern UpgradeCenter *TheUpgradeCenter;
NameKeyType NAMEKEY(const char *name);

// ?friend_applyDifficultyBonusesForObject@Player@@QAEXPAVObject@@_N@Z
void Player::friend_applyDifficultyBonusesForObject(Object *obj, Bool apply)
{
	if (!apply)
		return;
	if (!obj)
		return;
	if (obj->bfmeIsComputerControlled())
		return;
	if (!obj->getControllingPlayer())
		return;
	if (!obj->getControllingPlayer()->m_playerTemplate)
		return;
	if (!obj->getControllingPlayer()->m_playerTemplate->m_receivesDifficultyBonus)
		return;

	AsciiString name;
	if (((GameLogicPortraitShim *)TheBfmeGameLogic)->isInMultiplayerOrSkirmishGame() && m_ai)
	{
		switch (m_ai->getAIDifficulty())
		{
		case DIFFICULTY_EASY:
			name.set("Upgrade_EasyAIMultiPlayer");
			break;
		case DIFFICULTY_NORMAL:
			name.set("Upgrade_MediumAIMultiPlayer");
			break;
		case DIFFICULTY_HARD:
			name.set("Upgrade_HardAIMultiPlayer");
			break;
		}
	}
	else
	{
		GameDifficulty difficulty = *(GameDifficulty *)((char *)TheBfmeGameLogic + 0x9C);
		switch (difficulty)
		{
		case DIFFICULTY_EASY:
			name.set("Upgrade_EasyAISinglePlayer");
			break;
		case DIFFICULTY_NORMAL:
			name.set("Upgrade_MediumAISinglePlayer");
			break;
		case DIFFICULTY_HARD:
			name.set("Upgrade_HardAISinglePlayer");
			break;
		}
	}

	const UpgradeTemplate *upgrade = TheUpgradeCenter->findUpgradeByKey(NAMEKEY(name.str()));
	if (upgrade)
		obj->giveUpgrade(upgrade);
}
